"""Compare matching native poses and play the current skinned character."""
from pathlib import Path
import json
ROOT = Path(__file__).resolve().parents[1]
STYLE = (ROOT/'tools/build_action_motion_review.py').read_text().split('<style>')[1].split('</style>')[0]
HTML = '''<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cổ Sư · Nhân vật liền khớp 0.44</title><style>__STYLE__
.compare{display:flex;gap:22px;flex-wrap:wrap;margin-top:24px;align-items:start}.crop{height:350px}.crop img{width:3328px;height:1170px}.caption{margin:0 0 8px;font-weight:600}.note{max-width:600px;flex:1;min-width:240px}[hidden]{display:none!important}.controls{row-gap:16px}.full{margin-bottom:20px}main{padding-top:26px}@media(max-width:650px){.compare{gap:22px}.crop{max-width:100%}}
</style><main><h1>Nhân vật liền khớp · 0.44</h1><p>Tay áo, lớp quấn tay, bàn tay và giày được chỉnh lại theo tỷ lệ concept. Vải uốn nhẹ ở khớp; cẳng tay hiện đúng phía trước khi gập. Xem trước/sau ở cùng tư thế, rồi kiểm khi chuyển động.</p>
<nav><a href="#sheets">Bảng đủ tám hướng</a><a href="#world">Trong game</a><a href="concept44_skin.json">Kiểm biến dạng</a><a href="concept43_transition_review.html">Chuỗi chuyển động · 0.43</a></nav>
<div class="controls"><label>Chế độ<select id="mode"><option value="compare">So sánh trước / sau</option><option value="motion">Xem chuyển động</option></select></label><label id="poseControl">Tư thế so sánh<select id="pose"><option value="0">Đứng</option><option value="1">Bước tới</option><option value="2">Nhấc chân</option><option value="3">Lấy đà kiếm</option><option value="4" selected>Ra kiếm</option><option value="5">Phòng thủ · gập khuỷu</option><option value="6">Giơ cuốc</option><option value="7">Hái lượm</option></select></label><label id="actionControl" hidden>Động tác<select id="action"><option value="walk">Đi</option><option value="run">Chạy</option><option value="attack" selected>Vung kiếm</option><option value="defend">Phòng thủ</option><option value="gather">Hái lượm</option><option value="mine">Khai khoáng</option></select></label><label>Giới tính<select id="body"><option value="0">Nam</option><option value="1">Nữ</option></select></label><label>Hướng<select id="direction"></select></label><label id="bonesControl" hidden>Lớp xem<select id="bones"><option value="0">Nhân vật</option><option value="1">Khớp xương</option></select></label></div>
<div id="playback" hidden><div class="controls" style="margin-top:20px"><label>Tốc độ<select id="speed"><option value="1">Trong game · 1×</option><option value=".5">Chậm · ½×</option><option value=".25">Rất chậm · ¼×</option></select></label><button id="prev" aria-label="Frame trước">←</button><button id="play" disabled>Phát</button><button id="next" aria-label="Frame sau">→</button></div><div class="scrub"><input id="slider" type="range" min="0" max="23" value="8" aria-label="Chọn frame"><output id="count"></output></div></div>
<div class="compare"><div id="beforePanel"><p class="caption">Trước · 0.43</p><div class="crop"><img id="before" alt="Nhân vật trước chỉnh sửa"></div></div><div><p class="caption" id="afterLabel">Sau · 0.44</p><div class="crop"><img id="focus" alt="Nhân vật với chi tiết liền khớp"></div></div><div class="note"><h2 id="name"></h2><p id="status" role="status"></p><p>Chọn <strong>Phòng thủ</strong> để kiểm cẳng tay khi khuỷu gập, <strong>Giơ cuốc</strong> để kiểm vai và lớp tay sau đầu. Trong chế độ chuyển động, dùng các phím ← / → để xem từng frame.</p><p class="legend">Ảnh từ renderer Godot thật. So sánh dùng cùng pose và ánh sáng; bản trước dùng atlas cũ. Vũ khí, bàn tay và đế giày giữ cứng; chỉ vải quanh khớp biến dạng. Lớp xương có bốn mốc gần nhất trong mỗi clip.</p></div></div>
<details id="sheets"><summary>Bảng đầy đủ · nam/nữ ở tám hướng</summary><img class="full" id="fullBefore" alt="Bảng nhân vật trước sửa"><img class="full" id="full" alt="Bảng nhân vật sau sửa"></details>
<details id="world"><summary>Nhân vật trong game và xưởng F6</summary><img class="full" src="concept44_world_gather_30.png" alt="Hái lượm trong thế giới"><img class="full" src="concept44_world_mine_30.png" alt="Khai khoáng trong thế giới"><img class="full" src="concept44_studio_mine.png" alt="Nhân vật trong F6"><a href="concept44_ingame.json">Kiểm input E / F6</a></details></main>
<script>
const clips=__CLIPS__,$=id=>document.getElementById(id),dirs=['S · xuống','SW · xuống trái','W · trái','NW · lên trái','N · lên','NE · lên phải','E · phải','SE · xuống phải'];let frame=8,timer=null,generation=0;const loaded=new Set();dirs.forEach((t,i)=>$('direction').add(new Option(t,i)));$('direction').value='6';
function imageURL(n,overlay=false){return overlay?`concept44_${$('action').value}_bones_${String(n).padStart(2,'0')}.png`:`concept44_${$('action').value}/frame${String(n).padStart(3,'0')}.png`}
function update(){const compare=$('mode').value==='compare',body=+$('body').value,d=+$('direction').value,a=$('action').value;for(const id of ['beforePanel','poseControl'])$(id).hidden=!compare;for(const id of ['actionControl','bonesControl','playback'])$(id).hidden=compare;$('fullBefore').hidden=!compare;let source,n=frame;if(compare){const p=$('pose').value.padStart(2,'0');source=`concept44_after_${p}.png`;$('before').src=$('fullBefore').src=`concept44_before_${p}.png`;$('status').textContent=$('pose').selectedOptions[0].text+' · cùng tư thế cho cả hai bản'}else{const overlay=$('bones').value==='1';if(overlay)n=[4,8,14,20].reduce((b,x)=>Math.abs(x-frame)<Math.abs(b-frame)?x:b,4);source=imageURL(n,overlay);$('status').textContent=`${$('action').selectedOptions[0].text} · ${(n*clips[a].duration/24).toFixed(2)} giây${overlay?' · mốc xương gần nhất':''}`}$('focus').src=$('full').src=source;for(const id of ['before','focus']){$(id).style.left=`${160-(160+d*320)*1.3}px`;$(id).style.top=`${325-(345+body*370)*1.3}px`}$('name').textContent=`${body?'Nữ':'Nam'} · ${dirs[d]}`;$('count').textContent=`${n+1} / 24`;$('slider').value=frame;$('afterLabel').textContent=compare?'Sau · 0.44':'Chuyển động · 0.44'}
function stop(){clearInterval(timer);timer=null;$('play').textContent='Phát'}function step(delta){frame=(frame+delta+24)%24;update()}
async function prepare(){const a=$('action').value,g=++generation;$('play').disabled=true;if(!loaded.has(a)){await Promise.all(Array.from({length:24},(_,n)=>new Promise((resolve,reject)=>{const img=new Image();img.onload=resolve;img.onerror=reject;img.src=`concept44_${a}/frame${String(n).padStart(3,'0')}.png`})));loaded.add(a)}if(g===generation)$('play').disabled=false}
function play(){if(timer){stop();return}timer=setInterval(()=>step(1),clips[$('action').value].duration*1000/24/+$('speed').value);$('play').textContent='Dừng'}
for(const id of ['mode','pose','action','body','direction','bones'])$(id).onchange=()=>{stop();update();if($('mode').value==='motion')prepare().catch(()=>{$('status').textContent='Không tải được frame.'})};$('play').onclick=play;$('prev').onclick=()=>{stop();step(-1)};$('next').onclick=()=>{stop();step(1)};$('slider').oninput=()=>{stop();frame=+$('slider').value;update()};$('speed').onchange=()=>{if(timer){stop();play()}};document.addEventListener('keydown',e=>{if($('mode').value!=='motion'||['SELECT','INPUT'].includes(e.target.tagName))return;if(e.code==='Space'){e.preventDefault();if(!$('play').disabled)play()}if(e.key==='ArrowLeft'){stop();step(-1)}if(e.key==='ArrowRight'){stop();step(1)}});update();
</script></html>'''
if __name__=='__main__':
    data=json.loads((ROOT/'artifacts/concept44_native.json').read_text())
    (ROOT/'artifacts/concept44_character_review.html').write_text(HTML.replace('__STYLE__',STYLE).replace('__CLIPS__',json.dumps(data['actions'])))
    print('Built native character comparison 0.44')
